"""G4 — شواهد تطبيقية جديدة (الجزء ٣): مفاهيم مساق C1 من C801 إلى C814."""

EX_C1 = {
 "C801": [
  "درّب المعلم طلابه على التناظر اللفظي بسؤال: «أبيض : ثلج :: أسود : ؟» فحلل الطلاب العلاقة في الزوج الأول: لون ومثال معبر عنه، ثم بحثوا العلاقة ذاتها في الخيارات فاخترا «فحم»، وتدربوا على صياغة العلاقة بجملة واضحة قبل النظر إلى الخيارات.",
  "في تدريب على اختبار القدرات، واجهت الطالبة سؤال تناظر: «سيف : محارب :: قلم : ؟» فتذكرت خطتها: سمي العلاقة أولاً — أداة صاحب المهنة — ثم طبقتها، فاخترت «كاتب» بدل الخيارات البعيدة، ووفّرت الوقت لأن القاعدة أرشدت إليها مباشرة.",
  "درّب الطالب نفسه في المنزل على عشرة أزواج تناظر يوميًا وسجل العلاقة بجوار كل زوج: سببية، وتباين، ووظيفة، فاكتشف أن أكثر أخطائه في العلاقات السببية، فصنف تدريبه بعدها على هذه الفئة حتى تخطت نسبة صوابه ثمانين بالمئة.",
  "واجه المتقدم سؤالًا: «جفاف : مطر :: عطش : ؟» وخُدع بخيار قريب لفظيًا لا علاقة له بالعلاقة، فتذكر أنه يجب اختبار العلاقة في الاتجاهين: من الجفاف إلى المطر علاقة نقص وعلاج، فطبقها على العطش فاختار الماء، ونجح."
 ],
 "C802": [
  "قدّم الاختبار قاعدة: «كل من سافر في الصيف عاد بكاميرا»، ثم سأل: «سالم عاد بكاميرا، فهل سافر في الصيف؟» فحذر الطلاب الأذكياء من قلب الاتجاه: العودة بكاميرا لا تثبت السفر، فكانت الإجابة الصحيحة أنها غير محتمة، وهذا نصب الفخ الأشهر في الاستنتاج اللفظي.",
  "درّب المعلم طلابه على الاستنتاج بقاعدة مزدوجة: «إن كان الطالب نظيف الملبس حصل على بطاقة»، ثم قدّم موقفين: طالب حصل على بطاقة، وطالب لم يحصل عليها، فطلب تحديد ما ينطبق قطعًا، وتعلم الطلاب التفريق بين المتبوع والمتبوع له في الشرط.",
  "واجه المتقدم عبارة: «لا يصح اختبار بلا هدوء»، وسُئل: هل يجب هدوء كل اختبار؟ فحلل صيغة النفي المركب: شرط الهدوء لازم للصحة لا للحضور، فأجاب بأن الهدوء متحقق في الاختبارات الصحيحة دائمًا، لا في كل موقف هادئ.",
  "في تدريب منزلي حلّت الطالبة عشرة أسئلة استنتاج مسجلة إجاباتها، وعدلت مع كل خطأ تدوين قاعدة الفشل: هل قلبت الشرط؟ هل أضفت معلومة غريبة؟ فخفّت أخطاؤها بنصف بعد أسبوع، لأن الخطأ أصبح له اسم قاعدة تدركه قبل الإجابة."
 ],
 "C803": [
  "عرض الاختبار متتالية: ٣، ٨، ١٣، ١٨، ...، فحسبت الطالبة الفروق فثبت خمسة، فأدركت القاعدة الجمعية وأتمت الحد الناقص بثلاثة وعشرين، ولم تضيع وقتًا في تجربة قواعد أعقد قبل حصر الفروق البسيطة أولًا.",
  "واجه الطالب متتالية: ٢، ٤، ٨، ١٦، ...، فوجد الفروق متزايدة لا ثابتة، فنظر إلى نسبة كل حد إلى ما قبله فثبت الازدواج، فكان الحد التالي اثنين وثلاثين، وتذكر خطته: إن لم تثبت الفروق فجرّب النسب.",
  "في تدريب متقدم ظهرت متتالية: ١، ١، ٢، ٣، ٥، ٨، ...، فتذكر الطالب نمط جمع الحدين السابقين بعد فحص الفروق دون فائدة، فأتم الحد بثلاثة عشر، وأثمرت خلفيته في الأنماط الشائعة كالفيبوناتشي حين لا تعمل القواعد الابتدائية.",
  "راجعت الطالبة خطأها في متتالية: ١٠٠، ٥٠، ٢٥، ...، إذ أجابت بالطرح من عشرين ظنًا في قاعدة طرحية، فعادت إلى النسب فوجدت النصف في كل خطوة، وأدركت خطأها: القاعدة التضاعفية الطرحية هي القسمة على اثنين، فكان الحد اثني عشر ونصفًا."
 ],
 "C804": [
  "في اختبار قدرات: «إذا قطع مسافر ثلث الطريق في ساعتين، فكم يحتاج لبقية الطريق بالمعدل نفسه؟» فحلل الطالب الوضع: الثلث في ساعتين يعني بقية ثلثين تحتاج إلى أربعة ساعات، وتجنب الخطأ الشائع بالرد ست ساعات لكامل الطريق.",
  "سُئلت الطالبة: «نسبة الأولاد إلى البنات في صف ثلاثين طالبًا ثلاثة إلى اثنين، فكم عدد الأولاد؟» فجمعت أجزاء النسبة: خمسة أجزاء تطابق ثلاثين، فالجزء ستة، والأولاد ثلاثة أجزاء فثمانية عشر، وتدربت على ترجمة النص إلى أجزاء قبل الحساب.",
  "واجه المتقدم نسبة مركبة: «تكفي كمية من العلف لعشرة أغنام ثلاثين يومًا، فكم يومًا تكفي خمسة أغنام؟» فأدرك العلاقة العكسية بين عدد الأغنام والمدة، فضاعف المدة إلى ستين يومًا، وتذكر أن التناسب العكسي يضرب لا يقسم.",
  "درّب المعلم طلابه على فك النسبة من الصيغة النصية: «ثلاثة أخماس الطلاب متفوقون وعددهم اثنان وعشرون»، فحاول الطلاب قسمة العدد على ثلاثة لإيجاد الخمس الواحد فوجدوه كسريًا غير صحيح، فأدركوا أن المعطيات لا تتسق مع نسبة صحيحة للأعداد الكلية، وأدركوا أهمية التحقق من قابلية القسمة قبل إتمام الحل."
 ],
 "C805": [
  "سُئل المتقدم عن ٩٨ × ٧ ذهنيًا، فاستثمر التقريب إلى مئة: مئة في سبعة تساوي سبعمئة، ثم طرح اثنين في سبعة أي أربعة عشر، فالناتج ستعمئة وستة وثمانون، ووفّر الوقت لأن الضرب بالمئة أسهل من الضرب المباشر بالتسعين وثمانية.",
  "في حصة تدريب، طلب المعلم جمع الأعداد من واحد إلى خمسة وعشرين ذهنيًا، فذكر طالب القاعدة: زوّج الحدود الطرفية ثم اضرب عدد الأزواج في ناتج الزوج؛ فجمع واحدًا مع خمسة وعشرين فأعطى ستة وعشرين، والأزواج اثنا عشر ونصفًا، فالناتج ثلاثمئة وخمسة وعشرون.",
  "واجهت الطالبة ٤٥ × ١١، فتذكرت حيلة الرقم الوسطي: انسخي ٤ ثم اجمعي ٤ و ٥ فتسعة في الوسط ثم انسخي ٥، فالناتج ٤٩٥، وتدربت على الحيلة بعد التحقق من صلاحيتها للاعداد ذات الرقمين فقط.",
  "سُئل الطالب عن ١٢٥ × ٨، فحوّل الرقم إلى جزء من الألف: ١٢٥ ثمن ألف، فثُمن ألف مضروبًا في ثمانية يساوي ألفًا، واستغنى عن جدول الضرب الطويل، ثم علّل في الصف لماذا أفادت حيلة التجزئة العشرية هنا تحديدًا."
 ],
 "C806": [
  "عرض الاختبار سلسلة رموز: ▲ ● ▲ ● ■ ▲ ● ▲ ● ■، فحدد الطالب وحدة الدورة بخمسة رموز ثم عدّ الموقع المطلوب فوقع على الثاني من الدورة، فأجاب بـ●، وتذكر منهجية: وحدة الدورة أولًا ثم حساب الموضع بالباقي بعد القسمة.",
  "في تدريب على الأنماط، ظهر نمط حروف: أ، ج، هـ، ...، فأدرك الطالب قاعدة تخطي حرف واحد في ترتيب الهجاء، وتوقع الحرف التالي «ز»، وتدرب على ترديد أبجدية مرقمة لسرعة الاستدلال في الاختبارات الزمنية.",
  "واجهت الطالبة نمطًا هجينًا: عدد يتبعه شكل يتغير حجمه، ففصلت المسارين: عالجت التسلسل العددي في أول سطر وعالجت تزايد حجم الشكل في سطر ثانٍ، ثم جمعت النتيجتين، فتعلمت تفكيك الأنماط المركبة إلى طبقات مستقلة.",
  "راجع الطالب خطأه في نمط دوري طوله أربعة وسُئل عن الموقع التاسع عشر، فأجاب بالرمز الثالث متجاهلًا الباقي؛ فعاد إلى القسمة: تسعة عشر مقسومة على أربعة فالباقي ثلاثة، والرمز هو الثالث، وتذكر أن الباقي هو مفتاح الموقع لا العدد الكلي."
 ],
 "C807": [
  "عرض الاختبار سؤال ترتيب: «خمسة طلاب بأطوال متفاوتة: سالم أطول من خالد، وناصر أقصر من خالد، ومجيد أطول من سالم... فمن الأطول؟» فبنى الطالب سلسلة من الأطول إلى الأقصر قليلًا قليلًا، فخرج الترتيب كاملًا قبل النظر إلى الخيارات.",
  "درّبت المعلمة طلابها على مقارنة: «أكره من الفضة ولا أحب الذهب، فأي المعادن أقل مودة عندي؟» فمرّروا السلسلة من الأقل إلى الأكثر ثم اختاروا الاستنتاج المطلوب، وتدربوا على رسم مخطط سهم واحد لكل مقارنة قبل الإجابة.",
  "واجه المتقدم ثلاث مقارنات في سؤال واحد عن ساعات وصول ثلاث فرق، فنظمه في جدول صغير: فريق، زمن، ترتيب، ثم قرأ الأسئلة من الجدول بدل تتبع النص مرة بعد مرة، ووفّر وقتًا وأخطاء إعادة القراءة.",
  "لخّصت الطالبة خطأها في سؤال ترتيب مكاني: نسيَت أن الأقرب بالقياس الموجب يعني الأصغر قيمة، فعادت لتثبيت قاعدة عقلية: قبل الحل اسأل ماذا يعني أكبر وأصغر هنا؟ فصارت المقارنة مرهونة بفهم اتجاه المعيار لا بالأرقام وحدها."
 ],
 "C808": [
  "عرض الاختبار مجموعة كلمات: نجار، حداد، خياط، صانع أدوات، مربط خيول، فسأل أيها لا ينتمي، فحلل الطالب السمة المشتركة: أربعتها مهن تصنيع تحوّل المواد، والمربط وظيفة تربية وحفظ، فاستبعد المربط، وتدرب على ذكر السمة المشتركة قبل الاستبعاد لا بعده.",
  "في تدريب التصنيف، ظهرت مجموعة: مثلث، مربع، خماسي، دائرة، فاختلفت الآراء: من استبعد الدائرة لانعدام الأضلاع، ومن استبعد الخماسي لفرادة العدد، فعلّم المعلم قاعدة سؤال الفصل: أي السمات أعظم عمومًا وأقل خلافًا في هذا الاختبار؟",
  "واجهت الطالبة سؤال استبعاد في حيوانات: أسد، نمر، ذئب، جمل، فحددت السمة: الافتراس المشترك بين الثلاثة الأولى، فاستبعدت الجمل، ثم تحدت نفسها بصياغة سبب واحد واضح لا موجة كلمات، فمنعت الاختيار بالانطباع.",
  "راجع الطالب خطأه في استبعاد: ظهرت في السؤال أسماء مواسم وشهور بينها اسم لا ينتمي إليها، فاستبعد خطأ اسمًا قريبًا لفظيًا من الشهور، فعاد إلى السؤال: ما السمة المشتركة الحقيقية؟ فذكر نفسه أن الاستبعاد سمة واحدة محكمة، لا ميل نحو السطح اللفظي."
 ],
 "C809": [
  "عرض الاختبار قضية: «كل من يجتهد ينجح، وسالم نجح»، فسُئل: هل يجتهد سالم بالضرورة؟ فذكر الطالب خطر القلب: القاعدة تقطع مع الاجتهاد النجاح لا بالعكس، فالإجابة: غير محتمة، وتدرب على رسم دائرة الاجتهاد داخل دائرة النجاح بدل الاعتماد على الكلمات.",
  "في تدريب على الاستدلال القضوي، قُدمت قاعدة: «إن كان الطالب غائبًا فلا يُسجل حضوره»، ثم حكم على طالب حاضر، فأدرك الطلاب أن القاعدة لا تقطع شيئًا عن الغائب الحاضر، وحذرهم المعلم من الاستدلال بالسلب من المتبوع إلى الشرط.",
  "واجهت المتقدمة قضية منفية: «لا سباحة بلا إشراف»، ففهمت أن الإشراف شرط لازم، وحكمت على موقف بإشراف: لا يعني ذلك بالضرورة وجود سباحة، فأحسنت التفريق بين اللازم الموجب والافتراض الفارغ، وهذا من أدق مواضع القضوي.",
  "درّب الطالب نفسه على ربط القضايا بالمخططات: رسم قاعدة «كل طير يبض» كدائرة داخل دائرة الحيوانات، ثم مركب عبارة عن طائر، فاستنتج يبض قطعًا، وتذكر منهجية تحويل القضية إلى مساحة قبل الحكم على الحالات."
 ],
 "C810": [
  "عرض الاختبار وصف اتجاهات: «سار محمد شمالًا ثلاث كيلومترات ثم شرقًا أربعًا، فما بعده عن نقطة البداية؟» فرسم الطالب المسار بمقياس واتجه إلى مثلث قائم الزوايا، فحسب الوتر بخمسة كيلومترات، وتذكر منهجية الرسم قبل الحساب في أسئلة الاتجاهات.",
  "سُئلت الطالبة عن وجه شخص عاد إلى بداية طريقه بعد أربعة اتجاهات متعاقبة، فرسمت المسار بأسهم صغيرة وتركت علامات الاتجاهات، فوجدت أنه عاد باتجاه الجنوب، وتجنب الخطأ الشائع بحساب الزوايا بالعين المجردة دون إتمام الرسم.",
  "واجه المتقدم سؤالًا عن اتجاه ظل في الصباح: الشمس شرقًا والظل يمتد غربًا لعمود، ثم مدار الوقت إلى الظهيرة، فوقع الطلاب في تحديث الاتجاه مع تغير الشمس، فتعلموا تثبيت لحظة السؤال وتحديد موضع الشمس عندها قبل الإجابة.",
  "في تدريب المسافات، ظهر سؤال: «يريد المعلم الوصول من المدرسة إلى الملعب بأقصر طريق، والطريق المستقيم مغلق، فما البديل؟» فحدد الطلاب البدائل المتاحة وحسبوا مجموع المسافات، وتدربوا على تجسيد المسألة في خريطة مبسطة قبل الاختيار."
 ],
 "C811": [
  "عرض الاختبار سؤال طي: «طُوِيت ورقة مرة ثم ثقب أطرافها، فكم ثقبًا عند فتحها؟» فجرّب الطالب فعليًا بورقة حقيقية في التدريب المنزلي، فوجد ثقبين، ثم تعلم انتقال الخبرة إلى الرسم الذهني: الورقة المزدوجة تضاعف الثقب عند كل طبقة.",
  "واجهت الطالبة سؤال مكعبات: شكل مركب من مكعبات صغيرة يسأل عن عددها مع مخفي خلفها، فنظمته في طبقات من الأسفل إلى الأعلى وعدت كل طبقة قائمة، فلم يضيع منها مكعب مخفي، وتذكر منهجية العد طبقةً طبقة في الأسئلة الفراغية.",
  "في تدريب التمثيل الفراغي، ظهر سؤال عن تدوير حرف هندسي: مضلع مدار مرة كاملة، فأي الشكلين يطابقه؟ فدوّر الطالب الشكل برأسه في الخيال خطوة درجة درجة، وتذكر قاعدة: التدوير يغير الاتجاه لا نسب الأضلاع، فحماها من مطابقة بالمظهر العام.",
  "راجع الطالب خطأه في سؤال ظل مثلث، إذ ظن الظل يشبه الشكل تمامًا، فعاد إلى مبدأ الإسقاط: الظل يقلص أحد البعدين فتتغير النسب، فخرج بقاعدة عقلية: الظل ليس صورة الشكل بل إسقاطه، ومنعته من تكرار الخطأ في الاختبار."
 ],
 "C812": [
  "عرض الاختبار جدول درجات أربعة طلاب في ثلاث مواد، وسأل عن الطالب صاحب أعلى معدل، فجمعت الطالبة درجات كل طالب في سطر واحد قبل المقارنة، ووفّرت الوقت لأن الجمع حسب السطر أنظم من القراءة العشوائية للخلايا.",
  "واجه المتقدم جدولًا بأعمدة سنوات وسؤالًا عن الفرق الأكبر بين سنتين متتاليتين، فحسب الفروق في عمود واحد ثم تتبع الصف الأعلى، وتذكر منهجية: حدد الصف أو العمود قبل الحساب، فلا تخلط بيانات الفئات المختلفة.",
  "في تدريب قراءة الجداول، ظهر جدول حضور طلاب في أسبوع، وسُئل: في أي يوم تجاوز الحضور ثمانين بالمئة؟ فمرّرت الطالبة عمود اليوم عن يوم بعده مع فحص النسبة لا العدد الكلي، وتذكر الفرق بين النسب والمقاديل المطلقة.",
  "سُئل الطلاب عن جدول يوضح أعمدة مبيعات ثلاثة فروع في أربع فصول، وسُئلوا عن الفرع الأكثر ثباتًا، فناقشوا معنى الثبات: أقل تغير بين الفصول، وحسبوا مدى كل فرع، ثم عللوا اختيارهم بالمعنى لا بالأرقام وحدها."
 ],
 "C813": [
  "عرض الاختبار أربع جمل عن يوم طالب بترتيب مبعثر: الاستيقاظ، ومغادرة المنزل، وحصة الرياضة، والعودة، فسأل عن الترتيب الصحيح، فرتبت الطالبة الأحداث على خط زمني صغير مرقمًا من الصباح إلى المساء، ووفّرت الترتيب بأقل من عشر ثوانٍ.",
  "واجه المتقدم سؤالًا في ترتيب مراحل ظاهرة طبيعية: تكاثر سحاب، وتهطال، وجريان، وبخر، فأدرك حلقة دائرية لا خطية، فبدأ من البخر وأعاد الحلقة، وتذكر منهجية: لا تفترض الترتيب الخطي قبل فحص طبيعة الدورة.",
  "درّبت المعلمة طلابها على سؤال ترتيب تاريخي: ثلاث أحداث في حياة رائد علمي، ففرزت التواريخ قبل قراءة التفاصيل، ورتبتها في جدول صغير، وتذكر قاعدة: الأرقام الزمنية مفاتيح أولية في ترتيب الأحداث قبل المنطق التفصيلي.",
  "راجع الطالب خطأه في ترتيب مراحل تجربة علمية: وضع القياس قبل تجهيز العينة، فعاد إلى منطق التجربة: تجهيز ثم قياس ثم تحليل، وتذكر منهجية: اقرأ كل جملة واسأل ماذا تتطلب من سابقتها؟ فكان الترتيب نتيجة اعتماد لا حدس."
 ],
 "C814": [
  "عرض الاختبار أربع عمليات: ١٠ = ٢ + ٨، ١٥ = ٣ + ١٢، ٢٠ = ٤ + ١٦، ...، فسأل عن العملية التالية، فلاحظ الطالب ثبات القالب: الحد الأول يزداد بواحد في كل سطر، والحد الثاني يزداد بأربعة، فاستنتج العملية الخامسة: ٢٥ = ٥ + ٢٠، وتذكر منهجية الاستقراء: قارن المتغيرات بين السطور لا القيم المعزولة.",
  "في تدريب الاستقراء، ظهر تسلسل أشكال: مثلث ثم مربع ثم خماسي، وسُئل عن الشكل التالي وعدد أضلاعه، فعدّ الطلاب الأضلاع: ثلاثة فأربعة فخمسة، فاستنتجوا أن التالي سداسي الأضلاع، وتدربوا على كتابة القاعدة المستنبطة بجملة واضحة قبل الإجابة.",
  "واجهت الطالبة نمطًا عدديًا مبهمًا: ٢، ٦، ١٢، ٢٠، ...، فجربت الفروق: أربعة فستة فثمانية، وهي تزداد بواحدين، فاستنتجت الفرق التالي عشرة، فكان الحد ثلاثين، وتذكر منهجية: عالج الفروق كسلسلة جديدة إذا لم تثبت قاعدة السلسلة الأصلية.",
  "درّب الطالب نفسه على استنباط قاعدة من أمثلة: كلمة تنعكس ثم يُضاف حرف في كل دورة، فرسم جدولًا بالأمثلة الثلاثة المتاحة وسجل ما ثابت وما يتغير، فاستنبط القاعدة وتوقع الحالة الرابعة، ثم اختبرها على مثال خامس متوفر، فتدرب على التحقق بعد الاستنتاج."
 ],
}
